package us.drullk.graphmachine.worldgen;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.levelgen.presets.WorldPreset;
import us.drullk.graphmachine.GraphMachine;

/**
 * Keys of the world presets this mod adds. The presets themselves are data, generated by datagen.
 *
 * <p>Written by Claude Code; conversation transcript: {@code llm/transcripts/transcript_2026-10-16_07-43_2aec7285-4ea5-4d89-ba3e-f516a9a7bde0.md}.
 */
public final class GraphPresets {
    /** The preset whose overworld is the class graph. It is in {@code #minecraft:extended}, so hold Alt in the world type button to see it. */
    public static final ResourceKey<WorldPreset> GRAPH = ResourceKey.create(Registries.WORLD_PRESET, Identifier.fromNamespaceAndPath(GraphMachine.MODID, "graph"));

    private GraphPresets() {
    }
}
